  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*the card id and password is validated and the input card exist,
   *the input card info and withdraw status
   *and number should be cleared*/
  ejectCard(): boolean {
    /*Definition Start*/
    let exist: boolean = l({
      logic: () => getRepository(BankCard).includes(this.InputCard),
      description: "BankCard.allInstance()->includes(InputCard)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => this.CardIDValidated,
        description: "CardIDValidated",
      })
        .and({
          logic: () => this.PasswordValidated,
          description: "PasswordValidated",
        })
        .and({
          logic: () => exist,
          description: "exist",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let ob: BankCard;
    return l({
      execute: () => (ob = new BankCard()),
      description: "ob.oclIsNew()",
    })
      .and({
        execute: () => (this.InputCard.CardStatus = CardStatus.NORMAL),
        description: "InputCard.CardStatus=CardStatus::NORMAL",
      })
      .and({
        execute: () => (this.InputCard.Balance = 0),
